// Package deployexport produces portable deployment files from the canvas
// (PRD F25): a docker-compose.yml with the installed services, Dockerfiles for
// the application components found in the workspace, and a .env.example that
// lists variable names. Connected components never become containers; they
// appear as environment-variable references. No generated file contains a
// secret value: variables are written by name only, and values that look like
// credentials in a service's own environment become references too.
package deployexport

import (
	"context"
	"fmt"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/nexio-developer-group/nexmesh/server/internal/audit"
	"github.com/nexio-developer-group/nexmesh/server/internal/catalog"
	"github.com/nexio-developer-group/nexmesh/server/internal/component"
	"github.com/nexio-developer-group/nexmesh/server/internal/domain"
	"github.com/nexio-developer-group/nexmesh/server/internal/runtime"
	"github.com/nexio-developer-group/nexmesh/server/internal/store"
	"github.com/nexio-developer-group/nexmesh/server/internal/wiring"
	"github.com/nexio-developer-group/nexmesh/server/internal/wsfs"
	"gopkg.in/yaml.v3"
)

type Service struct {
	st    store.Store
	cat   *catalog.Catalog
	comp  *component.Service
	wires *wiring.Service
	fs    *wsfs.FS
	aud   *audit.Recorder
}

func New(st store.Store, cat *catalog.Catalog, comp *component.Service, wires *wiring.Service, fs *wsfs.FS, aud *audit.Recorder) *Service {
	return &Service{st: st, cat: cat, comp: comp, wires: wires, fs: fs, aud: aud}
}

// File is one generated file.
type File struct {
	Path    string `json:"path"`
	Content string `json:"content"`
	// Exists is true when the workspace already has a file at this path.
	Exists bool `json:"exists"`
	// Ours is true when that existing file was generated by Nexmesh, so it can be regenerated.
	Ours bool `json:"ours"`
}

type Plan struct {
	Files []File   `json:"files"`
	Notes []string `json:"notes"`
}

var secretish = regexp.MustCompile(`(?i)(pass|secret|token|key|credential)`)
var unsafeName = regexp.MustCompile(`[^a-z0-9_-]+`)

func serviceName(s string) string {
	s = strings.Trim(unsafeName.ReplaceAllString(strings.ToLower(s), "-"), "-")
	if s == "" {
		return "app"
	}
	return s
}

// Build plans the files. Nothing is written.
func (s *Service) Build(ctx context.Context, owner, wsID string) (*Plan, error) {
	w, err := s.st.GetWorkspace(ctx, wsID)
	if err != nil || w.OwnerID != owner {
		return nil, store.ErrNotFound
	}
	comps, err := s.st.ListComponents(ctx, wsID)
	if err != nil {
		return nil, err
	}
	wireViews, err := s.wires.List(ctx, owner, wsID)
	if err != nil {
		return nil, err
	}
	plan := &Plan{Files: []File{}, Notes: []string{}}

	versions := map[string]string{}
	for name, rs := range w.Runtimes {
		if rs.Active != "" {
			versions[name] = rs.Active
		}
	}
	projects, err := s.detect(ctx, wsID)
	if err != nil {
		plan.Notes = append(plan.Notes, "Could not read the workspace files ("+err.Error()+"), so no Dockerfiles were generated. Start the workspace and try again.")
	}
	claimed := map[*Project]bool{}

	type svc = map[string]any
	services := map[string]svc{}
	volumes := map[string]any{}
	envNames := map[string]string{} // name -> comment
	names := map[string]string{}    // card id -> compose service name
	taken := map[string]bool{}
	pick := func(base string) string {
		n := serviceName(base)
		for i := 2; taken[n]; i++ {
			n = fmt.Sprintf("%s-%d", serviceName(base), i)
		}
		taken[n] = true
		return n
	}

	sort.SliceStable(comps, func(i, j int) bool { return comps[i].CreatedAt.Before(comps[j].CreatedAt) })

	// 1. Installed services become containers; connected cards never do.
	for _, c := range comps {
		def, ok := s.cat.Get(c.CatalogID)
		if !ok {
			continue
		}
		switch {
		case c.Mode == domain.ModeInstalled && def.Install != nil && def.Install.Strategy == "image":
			name := pick(def.ID)
			names[c.ID] = name
			sv := svc{"image": def.Install.Image + ":" + c.Version, "restart": "unless-stopped"}
			if def.Install.ServiceCommand != nil {
				sv["command"] = def.Install.ServiceCommand
			}
			if ports := servicePorts(def, c); len(ports) > 0 {
				sv["ports"] = ports
			}
			var vols []string
			for _, v := range def.Install.Volumes {
				vn := name + "_" + v.Name
				volumes[vn] = map[string]any{}
				vols = append(vols, vn+":"+v.Path)
			}
			if len(vols) > 0 {
				sv["volumes"] = vols
			}
			if len(def.Install.Env) > 0 {
				env := map[string]any{}
				keys := make([]string, 0, len(def.Install.Env))
				for k := range def.Install.Env {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					if secretish.MatchString(k) {
						env[k] = "${" + k + "}"
						envNames[k] = "required by " + def.Name + ": choose a value"
					} else {
						env[k] = def.Install.Env[k]
					}
				}
				sv["environment"] = env
			}
			services[name] = sv
		case c.Mode == domain.ModeConnected:
			plan.Notes = append(plan.Notes, fmt.Sprintf("%s is a connected service, so it is not a container: its variables are references in .env.example.", label(def, c)))
		}
	}

	// 2. Application components found in the workspace get a Dockerfile and a service.
	appIDs := map[string]bool{"nestjs": true, "fastapi": true, "react": true, "angular": true, "htmlcss": true, "nodejs": true, "python": true, "go": true}
	for _, c := range comps {
		def, ok := s.cat.Get(c.CatalogID)
		if !ok || !appIDs[def.ID] || c.Mode != domain.ModeInstalled {
			continue
		}
		var found *Project
		for _, p := range projects {
			if !claimed[p] && p.matches(def.ID) {
				found = p
				break
			}
		}
		if found == nil {
			if err == nil {
				plan.Notes = append(plan.Notes, fmt.Sprintf("No %s project was found in the workspace, so %s has no Dockerfile or compose service. Create the project, then export again.", def.Name, def.Name))
			}
			continue
		}
		claimed[found] = true
		dirName := found.Dir
		base := dirName
		if base == "" {
			base = def.ID
		}
		name := pick(base)
		names[c.ID] = name
		port := appPort(def, c)
		df := path.Join(found.Dir, "Dockerfile")
		plan.Files = append(plan.Files, File{Path: df, Content: dockerfile(def.ID, found, versions, port)})
		if !(def.ID == "htmlcss" || found.Kind == "go") {
			plan.Files = append(plan.Files, File{Path: path.Join(found.Dir, ".dockerignore"), Content: dockerignore})
		}
		ctxDir := "."
		if found.Dir != "" {
			ctxDir = "./" + found.Dir
		}
		sv := svc{"build": map[string]any{"context": ctxDir}, "restart": "unless-stopped"}
		if port > 0 {
			hostPort := port
			cport := port
			if def.Kind == "framework" && (def.ID == "react" || def.ID == "angular" || def.ID == "htmlcss") {
				cport = 80 // served by nginx
			}
			sv["ports"] = []string{fmt.Sprintf("%d:%d", hostPort, cport)}
		} else if def.ID == "htmlcss" || def.ID == "react" || def.ID == "angular" {
			sv["ports"] = []string{"8080:80"}
		}
		services[name] = sv
	}

	// 3. Lines become environment: names only for connected providers, literal
	// non-secret values for installed ones (they are only service host names).
	for _, wv := range wireViews {
		consumerName, ok := names[wv.FromID]
		if !ok {
			continue
		}
		provider, err := s.st.GetComponent(ctx, wv.ToID)
		if err != nil {
			continue
		}
		pdef, ok := s.cat.Get(provider.CatalogID)
		if !ok {
			continue
		}
		env, _ := services[consumerName]["environment"].(map[string]any)
		if env == nil {
			env = map[string]any{}
		}
		switch {
		case provider.Mode == domain.ModeInstalled && pdef.Kind == "service":
			for k, v := range s.comp.WireValues(ctx, provider, wv.Name) {
				env[k] = v // installed services have no credentials: host and port only
			}
			if pn, ok := names[provider.ID]; ok {
				addDep(services[consumerName], pn)
			}
		case provider.Mode == domain.ModeInstalled:
			// Another application: reachable by its service name inside compose.
			pn := names[provider.ID]
			prefix := strings.ToUpper(strings.ReplaceAll(wv.Name, "-", "_"))
			if pn != "" {
				port := appPort(pdef, provider)
				env[prefix+"_URL"] = fmt.Sprintf("${%s_URL:-http://localhost:%d}", prefix, port)
				env[prefix+"_PORT"] = strconv.Itoa(port)
				envNames[prefix+"_URL"] = "address of " + label(pdef, provider) + " as seen by the browser"
				addDep(services[consumerName], pn)
			}
		default:
			for _, vn := range wv.Variables {
				env[vn] = "${" + vn + "}"
				envNames[vn] = "from the " + label(pdef, provider) + " connection (value kept in Nexmesh)"
			}
		}
		if len(env) > 0 {
			services[consumerName]["environment"] = env
		}
	}

	// Workspace variables are listed by name only.
	for _, v := range w.Variables {
		if v.ComponentID != "" || v.Environment != "" && v.Environment != domain.EnvDevelopment {
			continue
		}
		if _, ok := envNames[v.Name]; !ok {
			c := "workspace variable"
			if v.Secret {
				c += " (secret)"
			}
			envNames[v.Name] = c
		}
	}

	if len(services) == 0 {
		plan.Notes = append(plan.Notes, "There is nothing to put in a compose file yet: install a service or add an application project to the workspace.")
	} else {
		doc := map[string]any{"name": serviceName(w.Name), "services": services}
		if len(volumes) > 0 {
			doc["volumes"] = volumes
		}
		composeYAML, err := marshalOrdered(doc)
		if err != nil {
			return nil, err
		}
		plan.Files = append([]File{{Path: "docker-compose.yml", Content: header + composeYAML}}, plan.Files...)
	}
	if len(services) > 0 && len(envNames) > 0 {
		plan.Files = append(plan.Files, File{Path: ".env.example", Content: envExample(envNames)})
	}

	// Which files already exist, and are they ours?
	for i := range plan.Files {
		f := &plan.Files[i]
		if ok, err := s.fs.Exists(ctx, wsID, f.Path); err == nil && ok {
			f.Exists = true
			if t, err := s.fs.Read(ctx, wsID, f.Path); err == nil {
				f.Ours = strings.Contains(t.Content, "Generated by Nexmesh")
			}
		}
	}
	if secretLeak(plan) {
		return nil, fmt.Errorf("refusing to export: a generated file would contain a secret value")
	}
	return plan, nil
}

func (s *Service) detect(ctx context.Context, wsID string) ([]*Project, error) {
	return Detect(ctx, s.fs, wsID)
}

func label(def *catalog.Component, c *domain.Component) string {
	if c.ConnName != "" {
		return def.Name + " (" + c.ConnName + ")"
	}
	return def.Name
}

func servicePorts(def *catalog.Component, c *domain.Component) []string {
	if def.Install == nil {
		return nil
	}
	var out []string
	for _, p := range def.Install.Ports {
		host := p
		if v, ok := c.Settings["port"].(float64); ok && len(def.Install.Ports) == 1 {
			host = int(v)
		}
		out = append(out, fmt.Sprintf("%d:%d", host, p))
	}
	return out
}

func appPort(def *catalog.Component, c *domain.Component) int {
	if v, ok := c.Settings["port"].(float64); ok && v > 0 {
		return int(v)
	}
	if len(def.Ports) > 0 {
		return def.Ports[0]
	}
	if def.Install != nil && len(def.Install.Ports) > 0 {
		return def.Install.Ports[0]
	}
	return 0
}

func addDep(sv map[string]any, name string) {
	deps, _ := sv["depends_on"].([]string)
	for _, d := range deps {
		if d == name {
			return
		}
	}
	sv["depends_on"] = append(deps, name)
}

func envExample(names map[string]string) string {
	keys := make([]string, 0, len(names))
	for k := range names {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString("# Generated by Nexmesh. Names only: fill in the values you need, and never commit real secrets.\n")
	for _, k := range keys {
		fmt.Fprintf(&b, "# %s\n%s=\n", names[k], k)
	}
	return b.String()
}

// marshalOrdered writes YAML with services, ports and so on in a stable order.
func marshalOrdered(doc map[string]any) (string, error) {
	var buf strings.Builder
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(doc); err != nil {
		return "", err
	}
	_ = enc.Close()
	return buf.String(), nil
}

var credentialsInURL = regexp.MustCompile(`://[^/\s:@$]+:[^/\s@$]+@`)

// secretLeak is a last check that no generated file carries credentials, in case
// a future template change introduces one. Values are never read from the
// secrets store in the first place; this guards the template output.
func secretLeak(plan *Plan) bool {
	for _, f := range plan.Files {
		if credentialsInURL.MatchString(f.Content) {
			return true
		}
	}
	return false
}

// WriteInput selects which planned files to write.
type WriteInput struct {
	Paths     []string `json:"paths"`
	Overwrite bool     `json:"overwrite"`
	Confirm   bool     `json:"confirm"`
}

type WriteResult struct {
	Written []string `json:"written"`
	Skipped []string `json:"skipped"` // existing files kept because overwrite was not requested
}

// Write puts the chosen files into the workspace. Existing files are kept
// unless overwrite is set; the user reviews the plan first (PRD F25: files are
// written to the repository for review).
func (s *Service) Write(ctx context.Context, owner, wsID string, in WriteInput) (*WriteResult, error) {
	if !in.Confirm {
		return nil, &runtime.ValidationError{Field: "confirm", Code: "confirmation_required", Message: "Confirm before files are written to the workspace."}
	}
	plan, err := s.Build(ctx, owner, wsID)
	if err != nil {
		return nil, err
	}
	want := map[string]bool{}
	for _, p := range in.Paths {
		want[p] = true
	}
	if len(want) == 0 {
		return nil, &runtime.ValidationError{Field: "paths", Code: "nothing_selected", Message: "Choose at least one file."}
	}
	res := &WriteResult{Written: []string{}, Skipped: []string{}}
	for _, f := range plan.Files {
		if !want[f.Path] {
			continue
		}
		delete(want, f.Path)
		if f.Exists && !in.Overwrite {
			res.Skipped = append(res.Skipped, f.Path)
			continue
		}
		if dir := path.Dir(f.Path); dir != "." {
			if ok, _ := s.fs.Exists(ctx, wsID, dir); !ok {
				if err := s.fs.Mkdir(ctx, wsID, dir); err != nil {
					return res, err
				}
			}
		}
		if err := s.fs.Write(ctx, wsID, f.Path, f.Content, zeroTime); err != nil {
			return res, err
		}
		res.Written = append(res.Written, f.Path)
	}
	for p := range want {
		return res, &runtime.ValidationError{Field: "paths", Code: "unknown_path", Message: "That file is not part of the plan: " + p}
	}
	s.aud.User(ctx, owner, wsID, "export.compose_write", "", map[string]any{"written": res.Written, "skipped": res.Skipped, "overwrite": in.Overwrite})
	return res, nil
}

var zeroTime time.Time
